import { createSlice } from "@reduxjs/toolkit";
import { destroyInstance } from "../conversations/conversations.slice.js";
import { createInstanceFull } from "../create-instance-full.js";
const initialState = {
  byConversationId: {}
};
const instanceModelOverridesSlice = createSlice({
  name: "instanceModelOverrides",
  initialState,
  reducers: {
    /**
     * Initialize the override layer for a new instance.
     * Copies baseSettings from the agent ONCE — never look up agentId again.
     */
    initInstanceOverrides(state, action) {
      const { conversationId, baseSettings = {} } = action.payload;
      state.byConversationId[conversationId] = {
        conversationId,
        baseSettings,
        overrides: {},
        removals: [],
        seededKeys: []
      };
    },
    /**
     * Set one or more override values.
     * If a key was previously in removals, it's moved to overrides.
     *
     * 🚨 MERGE-ONLY. It upserts the incoming keys and NEVER removes one, so
     * re-sending the map without a key does NOT clear that key. Use
     * `resetOverride` (back to the agent default), `markRemoved` (explicitly
     * suppress), or `replaceOverrides` (whole-document replace).
     * (Defect 2026-09-12: the per-column Clear chip re-sent the map minus a
     * key and silently did nothing.)
     */
    setOverrides(state, action) {
      const { conversationId, changes } = action.payload;
      const entry = state.byConversationId[conversationId];
      if (entry) {
        Object.assign(entry.overrides, changes);
        const changedKeys = Object.keys(changes);
        entry.removals = entry.removals.filter((k) => !changedKeys.includes(k));
        entry.seededKeys = (entry.seededKeys ?? []).filter(
          (k) => !changedKeys.includes(k)
        );
      }
    },
    /**
     * A LAUNCH default for this conversation's agent (caller config, shortcut,
     * the person's default-chat-model preference). Same merge as
     * `setOverrides`, but the keys are recorded as seeded so an agent switch
     * never carries them to another agent (launch-model-overrides.ts).
     */
    seedOverrides(state, action) {
      const { conversationId, changes } = action.payload;
      const entry = state.byConversationId[conversationId];
      if (!entry) return;
      Object.assign(entry.overrides, changes);
      const changedKeys = Object.keys(changes);
      entry.removals = entry.removals.filter((k) => !changedKeys.includes(k));
      const seeded = new Set(entry.seededKeys ?? []);
      for (const key of changedKeys) seeded.add(key);
      entry.seededKeys = [...seeded];
    },
    /** Replace the editable override document, preserving its base snapshot.
     * JSON null has the same removal meaning as the individual controls.
     */
    replaceOverrides(state, action) {
      const entry = state.byConversationId[action.payload.conversationId];
      if (!entry) return;
      const overrides = {};
      const removals = [];
      for (const [key, value] of Object.entries(action.payload.changes)) {
        if (value === null) removals.push(key);
        else overrides[key] = value;
      }
      entry.overrides = overrides;
      entry.removals = removals;
      entry.seededKeys = [];
    },
    /**
     * Mark a setting key as explicitly removed.
     * Removes it from overrides if present.
     */
    markRemoved(state, action) {
      const { conversationId, key } = action.payload;
      const entry = state.byConversationId[conversationId];
      if (entry) {
        delete entry.overrides[key];
        if (!entry.removals.includes(key)) {
          entry.removals.push(key);
        }
        entry.seededKeys = (entry.seededKeys ?? []).filter((k) => k !== key);
      }
    },
    /**
     * Reset a key to "untouched" — remove from both overrides and removals.
     * The setting falls through to the agent's default.
     */
    resetOverride(state, action) {
      const { conversationId, key } = action.payload;
      const entry = state.byConversationId[conversationId];
      if (entry) {
        delete entry.overrides[key];
        entry.removals = entry.removals.filter((k) => k !== key);
        entry.seededKeys = (entry.seededKeys ?? []).filter((k) => k !== key);
      }
    },
    /**
     * Replace the baseSettings snapshot for an existing instance.
     * Called by the builder sync saga when settings change on the agent
     * definition while an instance is already live.
     *
     * ONLY replaces baseSettings — overrides and removals are untouched so
     * any explicit user overrides set during the builder session are preserved.
     */
    updateBaseSettings(state, action) {
      const entry = state.byConversationId[action.payload.conversationId];
      if (entry) {
        entry.baseSettings = action.payload.baseSettings;
      }
    },
    /**
     * Reset ALL overrides for an instance — back to pure agent defaults.
     */
    resetAllOverrides(state, action) {
      const entry = state.byConversationId[action.payload];
      if (entry) {
        entry.overrides = {};
        entry.removals = [];
        entry.seededKeys = [];
      }
    },
    /**
     * Clean up when an instance is destroyed.
     */
    removeInstanceOverrides(state, action) {
      delete state.byConversationId[action.payload];
    }
  },
  extraReducers: (builder) => {
    builder.addCase(createInstanceFull, (state, action) => {
      const { conversationId, overrides } = action.payload;
      if (!overrides) return;
      const previous = state.byConversationId[conversationId];
      state.byConversationId[conversationId] = {
        conversationId,
        baseSettings: overrides.baseSettings ?? {},
        overrides: previous?.overrides ?? {},
        removals: previous?.removals ?? [],
        seededKeys: previous?.seededKeys ?? []
      };
    });
    builder.addCase(destroyInstance, (state, action) => {
      delete state.byConversationId[action.payload];
    });
  }
});
const {
  initInstanceOverrides,
  setOverrides,
  seedOverrides,
  replaceOverrides,
  markRemoved,
  resetOverride,
  resetAllOverrides,
  updateBaseSettings,
  removeInstanceOverrides
} = instanceModelOverridesSlice.actions;
var instance_model_overrides_slice_default = instanceModelOverridesSlice.reducer;
export {
  instance_model_overrides_slice_default as default,
  initInstanceOverrides,
  markRemoved,
  removeInstanceOverrides,
  replaceOverrides,
  resetAllOverrides,
  resetOverride,
  seedOverrides,
  setOverrides,
  updateBaseSettings
};
